#include <stdio.h>

#define SIZE 3

int items[SIZE];
int head = 0;
int tail = 0;

void add(int v) {
    items[tail] = v;
    tail = (tail + 1) % SIZE;
}

int take() {
    int v = items[head];
    head = (head + 1) % SIZE;
    return v;
}

int main() {
    add(1);
    add(2);
    printf("%d\n", take());
    add(3);
    add(4);
    printf("%d\n", take());
    printf("%d\n", take());
    printf("%d\n", take());
    return 0;
}
